(()=>{let dialog,lastFocus;document.addEventListener('click',event=>{const link=event.target.closest('a.photo-open');if(!link||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;if(!window.HTMLDialogElement)return;event.preventDefault();if(!dialog){dialog=document.createElement('dialog');dialog.className='photo-viewer';dialog.setAttribute('aria-label','Просмотр фотографии');const close=document.createElement('button');close.type='button';close.textContent='×';close.setAttribute('aria-label','Закрыть фотографию');close.addEventListener('click',()=>dialog.close());dialog.append(close,document.createElement('img'));document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>lastFocus?.focus());}lastFocus=link;const image=dialog.querySelector('img');image.src=link.href;image.alt=link.querySelector('img')?.alt||'Фото техники';dialog.showModal();});})();
